/* ---- ccode (std) ----------------------------------------------------------- */
static char* lar_process_copy(const char* s) {
        size_t n = strlen(s);
        char* c = (char*)malloc(n + 1);
        if (!c) lar_panic("out of memory starting a process", 0);
        memcpy(c, s, n + 1);
        return c;
    }

    static void lar_process_push(char*** list, int* count, const char* s) {
        char** grown = (char**)realloc(*list, sizeof(char*) * (size_t)(*count + 2));
        if (!grown) lar_panic("out of memory starting a process", 0);
        grown[*count] = lar_process_copy(s);
        grown[*count + 1] = NULL;
        *list = grown;
        *count += 1;
    }


