/* ---- Prototypes ------------------------------------------------------------ */
static bool lar_text_is_float(const char* s, int32_t n) {
    char* end = NULL;
    if (n == 0 || n >= 64 || (int32_t)strlen(s) != n) return false;
    if (s[0] == ' ' || s[0] == '\t' || s[0] == '\n' || s[0] == '\r' || s[0] == '\f' || s[0] == '\v') return false;
    (void)strtod(s, &end);
    return end == s + n;
}
static double lar_text_to_float(const char* s) {
    return strtod(s, NULL);
}
static LarNative_std__lang__TextBuf lar_text_buf_new(LarMemory* m) {
    TextBuf* b = (TextBuf*)lar_memory_alloc(m, sizeof(TextBuf), 0);
    b->mem = m;
    b->cap = 32;
    b->buf = (char*)lar_memory_alloc(m, (size_t)b->cap, 0);
    return b;
}
static void lar_text_buf_add(LarNative_std__lang__TextBuf b, const char* text) {
    int32_t n = (int32_t)strlen(text);
    if (n > INT32_MAX - b->len) lar_panic("text is too large", 0);
    int32_t need = b->len + n + 1;
    if (need > b->cap) {
        int32_t cap = b->cap;
        while (cap < need) {
            if (cap > INT32_MAX / 2) { cap = need; break; }
            cap *= 2;
        }
        char* next = (char*)lar_memory_alloc(b->mem, (size_t)cap, 0);
        if (b->len > 0) memcpy(next, b->buf, (size_t)b->len);
        b->buf = next;
        b->cap = cap;
    }
    if (n > 0) memcpy(b->buf + b->len, text, (size_t)n);
    b->len += n;
    b->buf[b->len] = 0;
}
static int32_t lar_text_buf_length(LarNative_std__lang__TextBuf b) {
    return b->len;
}
static const char* lar_text_buf_view(LarNative_std__lang__TextBuf b) {
    return b->buf;
}
static void lar_text_buf_clear(LarNative_std__lang__TextBuf b) {
    b->len = 0; if (b->buf) b->buf[0] = 0;
}
static LarNative_std__lang__ByteText lar_byte_text_sized(LarMemory* m, int32_t n) {
    ByteText* t = (ByteText*)lar_memory_alloc(m, sizeof(ByteText), 0);
    t->mem = m;
    t->capacity = (n > 0 ? n : 0) + 1;
    t->bytes = (char*)lar_memory_alloc(m, (size_t)t->capacity, 0);
    return t;
}
