static LarString clone_s(LarString v, LarMemory* mem, LarCloneMap* cm) {
    (void)cm;
    if (lar_clone_keeps(cm, v.ptr)) return v;
    return lar_string_clone(v, mem, 0);
}

static List_u8* clone_Lu8(List_u8* v, LarMemory* mem, LarCloneMap* cm) {
    (void)cm;
    if (lar_clone_keeps(cm, v)) return v;
    if (cm->only) { void* done = lar_clone_get(cm, v); if (done) return (List_u8*)done; }
    List_u8* r = List_u8_new(mem, 0);
    if (cm->only) lar_clone_put(cm, v, r);
    for (int32_t i = 0; i < v->length; i++) List_u8_add(r, v->items[i], 0);
    return r;
}

